    /**
     * An interface that defines how to map each variant of [BetaResponsesServerEvent] to a value of
     * type [T].
     */
    interface Visitor<out T> {

        /** Emitted when there is a partial audio response. */
        fun visitResponseAudioDelta(responseAudioDelta: BetaResponseAudioWsDelta): T

        /** Emitted when the audio response is complete. */
        fun visitResponseAudioDone(responseAudioDone: BetaResponseAudioWsDone): T

        /** Emitted when there is a partial transcript of audio. */
        fun visitResponseAudioTranscriptDelta(
            responseAudioTranscriptDelta: BetaResponseAudioTranscriptWsDelta
        ): T

        /** Emitted when the full audio transcript is completed. */
        fun visitResponseAudioTranscriptDone(
            responseAudioTranscriptDone: BetaResponseAudioTranscriptWsDone
        ): T

        /** Emitted when a partial code snippet is streamed by the code interpreter. */
        fun visitResponseCodeInterpreterCallCodeDelta(
            responseCodeInterpreterCallCodeDelta: BetaResponseCodeInterpreterCallCodeWsDelta
        ): T

        /** Emitted when the code snippet is finalized by the code interpreter. */
        fun visitResponseCodeInterpreterCallCodeDone(
            responseCodeInterpreterCallCodeDone: BetaResponseCodeInterpreterCallCodeWsDone
        ): T

        /** Emitted when the code interpreter call is completed. */
        fun visitResponseCodeInterpreterCallCompleted(
            responseCodeInterpreterCallCompleted: BetaResponseCodeInterpreterCallWsCompleted
        ): T

